INSERT INTO pages (url_slug, location_city_id, service_id, content_json, status, published_at) SELECT '/car-shipping/ca/los-angeles', c.id, sv.id, '{"headline": "Los Angeles car shipping, matched with a licensed carrier", "intro": "From sedans to SUVs and classic cars, we help Los Angeles-area shippers find a carrier that fits their route, timeline, and budget.", "faq": [{"q": "How is my Los Angeles shipping quote calculated?", "a": "Your quote is based on the distance from Los Angeles, the type of vehicle being shipped, and current carrier demand on this route."}, {"q": "Do I have to pay anything upfront?", "a": "No. Payment is due once a carrier is dispatched to your Los Angeles pickup location \u2014 standard practice among reputable brokers."}, {"q": "How do you vet carriers serving Los Angeles?", "a": "We verify each carrier''s operating license and safety history, and pull a certified copy of their insurance directly from the issuing agency before booking."}, {"q": "How long does delivery take from Los Angeles?", "a": "Most continental U.S. routes take 1\u20137 days depending on distance; you''ll get an estimated window once matched with a carrier."}]}'::jsonb, 'published', now() FROM cities c JOIN states s ON c.state_id = s.id, services sv WHERE c.name = 'Los Angeles' AND s.abbreviation = 'CA' AND sv.slug = 'car-shipping' ON CONFLICT (url_slug) DO NOTHING;
INSERT INTO pages (url_slug, location_city_id, service_id, content_json, status, published_at) SELECT '/freight-shipping/ca/los-angeles', c.id, sv.id, '{"headline": "Move your freight in or out of Los Angeles with a vetted carrier", "intro": "We match Los Angeles shippers with vetted freight carriers experienced in your cargo type, weight class, and delivery window.", "faq": [{"q": "How is my Los Angeles shipping quote calculated?", "a": "Pricing reflects the route distance, shipment type, and current seasonal demand on this lane \u2014 not a low-ball number designed to change later."}, {"q": "Do I have to pay anything upfront?", "a": "Payment isn''t due until a carrier is actually dispatched for pickup in Los Angeles, which is standard in this industry."}, {"q": "How do you vet carriers serving Los Angeles?", "a": "We verify each carrier''s operating license and safety history, and pull a certified copy of their insurance directly from the issuing agency before booking."}, {"q": "How long does delivery take from Los Angeles?", "a": "Transit time depends on distance, but most routes from Los Angeles fall in the 1\u20137 day range once a carrier is assigned."}]}'::jsonb, 'published', now() FROM cities c JOIN states s ON c.state_id = s.id, services sv WHERE c.name = 'Los Angeles' AND s.abbreviation = 'CA' AND sv.slug = 'freight-shipping' ON CONFLICT (url_slug) DO NOTHING;
INSERT INTO pages (url_slug, location_city_id, service_id, content_json, status, published_at) SELECT '/container-shipping/ca/los-angeles', c.id, sv.id, '{"headline": "Container shipping serving Los Angeles, California", "intro": "We match Los Angeles container shipments with carriers experienced in FCL and LCL moves through the region''s ports and rail yards.", "faq": [{"q": "How is my Los Angeles shipping quote calculated?", "a": "Pricing reflects the route distance, container type, and current seasonal demand on this lane \u2014 not a low-ball number designed to change later."}, {"q": "Do I have to pay anything upfront?", "a": "No. Payment is due once a carrier is dispatched to your Los Angeles pickup location \u2014 standard practice among reputable brokers."}, {"q": "How do you vet carriers serving Los Angeles?", "a": "We verify each carrier''s operating license and safety history, and pull a certified copy of their insurance directly from the issuing agency before booking."}, {"q": "How long does delivery take from Los Angeles?", "a": "Transit time depends on distance, but most routes from Los Angeles fall in the 1\u20137 day range once a carrier is assigned."}]}'::jsonb, 'published', now() FROM cities c JOIN states s ON c.state_id = s.id, services sv WHERE c.name = 'Los Angeles' AND s.abbreviation = 'CA' AND sv.slug = 'container-shipping' ON CONFLICT (url_slug) DO NOTHING;
