INSERT INTO pages (url_slug, location_city_id, service_id, content_json, status, published_at) SELECT '/freight-shipping/me/bangor', c.id, sv.id, '{"headline": "Move your freight in or out of Bangor with a vetted carrier", "intro": "We match Bangor shippers with vetted freight carriers experienced in your cargo type, weight class, and delivery window.", "faq": [{"q": "How is my Bangor shipping quote calculated?", "a": "Pricing reflects the route distance, shipment type, and current seasonal demand on this lane \u2014 not a low-ball number designed to change later."}, {"q": "Do I have to pay anything upfront?", "a": "No. Payment is due once a carrier is dispatched to your Bangor pickup location \u2014 standard practice among reputable brokers."}, {"q": "How do you vet carriers serving Bangor?", "a": "We verify each carrier''s operating license and safety history, and pull a certified copy of their insurance directly from the issuing agency before booking."}, {"q": "How long does delivery take from Bangor?", "a": "Transit time depends on distance, but most routes from Bangor fall in the 1\u20137 day range once a carrier is assigned."}]}'::jsonb, 'published', now() FROM cities c JOIN states s ON c.state_id = s.id, services sv WHERE c.name = 'Bangor' AND s.abbreviation = 'ME' AND sv.slug = 'freight-shipping' ON CONFLICT (url_slug) DO NOTHING;